<script setup>
import { communicationPayload } from '../../../services/communication-urls.js'
import {ref,computed,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import axios from 'axios'
import { API_BASE_URL } from '../../../services/http.js'
const route=useRoute(),catalog=ref(null),error=ref(''),search=ref(''),category=ref('Todos'),notice=ref(''),selected=ref(null)
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const categories=computed(()=>['Todos',...new Set(catalog.value?.products.map(p=>p.category)||[])])
const products=computed(()=>catalog.value?.products.filter(p=>(category.value==='Todos'||p.category===category.value)&&`${p.name} ${p.code} ${p.description||''}`.toLowerCase().includes(search.value.toLowerCase()))||[])
function command(operation){return catalog.value?.commands?.find(c=>c.operation===operation)?.command||({'add':'/add','remove':'/remove','confirm':'/confirmar','finalize':'/finalizar'})[operation]}
async function copy(product){try{await navigator.clipboard.writeText(command('add')+' '+product.code);notice.value='Comando copiado! Cole na conversa do WhatsApp.'}catch{notice.value='Na conversa do WhatsApp, digite: '+command('add')+' '+product.code}}
onMounted(async()=>{try{catalog.value=communicationPayload((await axios.get(`${API_BASE_URL.replace(/\/$/, '')}/whatsapp-web/public/catalog/`+encodeURIComponent(route.params.slug))).data);document.title=catalog.value.title+' · Catálogo'}catch{error.value='Este catálogo não está disponível no momento.'}})
</script>
<template><div class="public-store"><header class="store-header"><a href="#menu" class="store-brand">🍔 <span>{{catalog?.title||'Catálogo'}}</span></a><span class="store-label">Escolha aqui. Peça pelo WhatsApp.</span></header><main id="menu"><div v-if="error" class="store-empty" role="alert">{{error}}</div><div v-else-if="!catalog" class="store-empty">Preparando o cardápio…</div><template v-else><section class="store-hero"><span class="eyebrow">Seu próximo favorito está aqui</span><h1>{{catalog.title}}</h1><p>{{catalog.description}}</p><div class="hero-chips"><span v-if="catalog.pickupAddress">🏪 Retirada disponível</span><span v-if="catalog.deliveryFeeCents!=null">🛵 Entrega {{money(catalog.deliveryFeeCents)}}</span><span>💬 IDs fáceis para pedir no chat</span></div></section><section class="store-controls"><label><span class="sr-only">Buscar produto ou ID</span><input v-model="search" placeholder="Busque por nome ou ID · BUGR1…" type="search"></label><nav aria-label="Categorias"><button v-for="item in categories" :key="item" :class="{chosen:category===item}" @click="category=item">{{item}}</button></nav></section><p v-if="notice" class="store-notice" role="status">{{notice}}</p><div class="store-grid"><article v-for="p in products" :key="p.code" class="product-card"><button v-if="p.media?.[0]?.kind==='image'" class="product-photo" @click="selected=p" :aria-label="'Ver foto de '+p.name"><img :src="p.media[0].url" :alt="p.name" loading="lazy" decoding="async" width="640" height="640"><span v-if="p.featured" class="most-loved">🔥 Mais pedido</span></button><div v-else class="product-placeholder">{{p.kind==='service'?'⚙️':'🍽️'}}</div><div class="product-info"><div class="product-top"><span>{{p.category}}</span><code>{{p.code}}</code></div><h2>{{p.name}}</h2><p>{{p.description}}</p><small v-if="p.stock!=null">{{p.stock}} disponível(is)</small><footer><strong>{{p.priceCents!=null?money(p.priceCents):'Consulte o atendente'}}</strong><button :disabled="!p.available||p.priceCents==null" @click="copy(p)">{{p.available?'Copiar '+command('add'):'Esgotado'}}</button></footer><button v-if="p.media?.length>1||p.media?.[0]&&p.media[0].kind!=='image'" class="media-link" @click="selected=p">Ver mídias do produto</button></div></article></div><p v-if="!products.length" class="store-empty">Nenhum item encontrado. Tente outra busca.</p><aside class="store-how"><h2>Seu pedido, do seu jeito.</h2><p>Volte à conversa do WhatsApp e use <b>{{command('add')}} ID quantidade</b>. Para remover: <b>{{command('remove')}} ID</b>. Confira com <b>{{command('confirm')}}</b> e envie com <b>{{command('finalize')}}</b>.</p><small>O preço e a disponibilidade são conferidos ao finalizar. O catálogo não efetua pagamentos.</small></aside><footer class="store-footer">{{catalog.title}}<span>{{catalog.pickupAddress}}</span></footer></template></main><div v-if="selected" class="photo-overlay" role="dialog" aria-modal="true" :aria-label="selected.name" @click.self="selected=null"><section><header><h2>{{selected.name}}</h2><button @click="selected=null" aria-label="Fechar imagem">×</button></header><div v-for="m in selected.media" :key="m.url"><img v-if="m.kind==='image'" :src="m.url" :alt="selected.name"><video v-else-if="m.kind==='video'" :src="m.url" controls preload="metadata"></video><audio v-else-if="m.kind==='audio'" :src="m.url" controls preload="metadata"></audio><a v-else :href="m.url" target="_blank" rel="noopener">{{m.name||'Abrir arquivo'}}</a></div></section></div></div></template>
<style scoped>
.public-store{min-height:100dvh;background:#11110f;color:#fff8eb;font-family:Inter,'Segoe UI',sans-serif}.store-header{display:flex;justify-content:space-between;align-items:center;padding:20px max(20px,calc((100vw - 1180px)/2));border-bottom:1px solid #35312a;background:#181713}.store-brand{display:flex;gap:10px;align-items:center;color:inherit;text-decoration:none;font-weight:800}.store-label{font-size:12px;color:#cabfa9}main{max-width:1180px;margin:auto;padding:0 24px}.store-hero{padding:64px 0 38px;max-width:760px}.eyebrow{color:#ffc45c;font-size:12px;text-transform:uppercase;letter-spacing:2px}.store-hero h1{font-size:clamp(36px,6vw,64px);line-height:1.05;letter-spacing:-2px;margin:18px 0}.store-hero p{font-size:17px;line-height:1.7;color:#d0c8b9}.hero-chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}.hero-chips span{padding:9px 14px;border:1px solid #4b4130;border-radius:22px;font-size:12px}.store-controls{position:sticky;top:0;z-index:5;background:#11110ff0;backdrop-filter:blur(16px);padding:16px 0;display:grid;gap:16px}.store-controls input{width:100%;background:#24221d;color:white;border:1px solid #554b39;border-radius:12px;padding:15px}.store-controls nav{display:flex;gap:8px;overflow:auto}.store-controls button{flex-shrink:0;padding:9px 17px;border:1px solid #514636;border-radius:24px;background:transparent;color:#d8cdbb;cursor:pointer}.store-controls button.chosen{background:#ffbc49;color:#241b0e;border-color:#ffbc49}.store-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin:20px 0 40px}.product-card{overflow:hidden;border:1px solid #443a2b;border-radius:20px;background:#1b1915}.product-photo{position:relative;display:block;width:100%;padding:0;border:0;background:#222;cursor:zoom-in;aspect-ratio:1}.product-photo img{display:block;width:100%;height:100%;object-fit:cover}.most-loved{position:absolute;left:15px;bottom:15px;padding:7px 12px;background:#ffbf51;color:#302311;border-radius:20px;font-size:12px;font-weight:800}.product-placeholder{display:grid;place-items:center;font-size:60px;aspect-ratio:1;background:#29251c}.product-info{padding:22px}.product-top{display:flex;justify-content:space-between;gap:12px;color:#c6af88;font-size:11px}.product-top code{border:1px solid #716044;border-radius:5px;padding:3px 6px;color:#ffca70}.product-info h2{font-size:22px;margin:15px 0 10px}.product-info p{color:#c8beac;font-size:13px;line-height:1.6;min-height:42px}.product-info footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:22px}.product-info strong{font-size:19px;color:#ffca70}.product-info button{padding:10px 13px;border:0;border-radius:10px;background:#ffbb48;color:#2d2009;font-weight:800;cursor:pointer}.product-info button:disabled{opacity:.45;cursor:default}.product-info .media-link{display:block;margin-top:15px;background:transparent;color:#ffca70}.store-how{border:1px solid #514532;border-radius:18px;padding:30px;background:#262117;line-height:1.8}.store-how h2{margin:0;font-size:24px}.store-how p,.store-how small{color:#d0c4ae}.store-footer{padding:32px 0;display:flex;justify-content:space-between;font-size:12px;color:#bbaa8a;gap:20px}.store-notice{padding:12px;background:#183f30;border-radius:10px}.store-empty{padding:60px 0;color:#e0cba7}.photo-overlay{position:fixed;inset:0;background:#000c;z-index:100;display:grid;place-items:center;padding:16px}.photo-overlay section{background:#211e18;border-radius:20px;padding:16px;max-width:800px;width:100%;max-height:95dvh;overflow:auto}.photo-overlay header{display:flex;justify-content:space-between;align-items:center;gap:15px}.photo-overlay h2{font-size:20px}.photo-overlay button{background:#fff2;border:0;border-radius:10px;color:white;padding:10px 15px}.photo-overlay img,.photo-overlay video{width:100%;height:auto;max-height:75dvh;object-fit:contain}.photo-overlay audio{width:100%}.photo-overlay a{color:#ffc76a}.sr-only{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}@media(max-width:850px){.store-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.store-label{display:none}}@media(max-width:520px){main{padding:0 16px}.store-hero{padding-top:38px}.store-grid{grid-template-columns:1fr}.store-footer{flex-direction:column}.store-how{padding:22px}}
</style>

